import {
  ChangeDetectionStrategy,
  Component,
  Injectable,
  computed,
  input,
  signal,
} from '@angular/core';

export type AevkoToastTone = 'default' | 'success' | 'info' | 'warning' | 'error';
export interface AevkoToastOptions {
  description?: string;
  tone?: AevkoToastTone;
  duration?: number;
  actionLabel?: string;
  action?: () => void;
}
export interface AevkoToastItem extends AevkoToastOptions {
  id: string;
  title: string;
}

@Injectable({ providedIn: 'root' })
export class AevkoToastStore {
  private readonly state = signal<readonly AevkoToastItem[]>([]);
  private nextId = 0;
  readonly toasts = computed(() => this.state());
  show(title: string, options: AevkoToastOptions = {}): string {
    const id = `aevko-toast-${++this.nextId}`;
    this.state.update((items) => [...items, { id, title, ...options }]);
    const duration = options.duration ?? 5000;
    if (duration > 0) setTimeout(() => this.dismiss(id), duration);
    return id;
  }
  dismiss(id: string): void {
    this.state.update((items) => items.filter((item) => item.id !== id));
  }
  clear(): void {
    this.state.set([]);
  }
  runAction(toast: AevkoToastItem): void {
    toast.action?.();
    this.dismiss(toast.id);
  }
}

@Component({
  selector: 'aevko-toaster',
  standalone: true,
  templateUrl: './toast.component.html',
  styleUrl: './toast.component.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { 'data-slot': 'toaster' },
})
export class AevkoToaster {
  readonly label = input('Notifications');
  constructor(protected readonly store: AevkoToastStore) {}
}

:host {
  display: contents;
}
.viewport {
  align-items: end;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  inset-block-end: 1rem;
  inset-inline-end: 1rem;
  max-inline-size: calc(100vw - 2rem);
  position: fixed;
  z-index: 60;
}
.toast {
  align-items: start;
  background: var(--aevko-surface, #fff);
  border: 1px solid var(--aevko-border, #e4e4e7);
  border-inline-start-width: 0.25rem;
  border-radius: 0;
  box-shadow: var(--aevko-shadow, 0 4px 16px rgb(0 0 0 / 0.08));
  color: var(--aevko-foreground, #171717);
  display: grid;
  gap: 0.75rem;
  grid-template-columns: 1fr auto auto;
  inline-size: min(24rem, calc(100vw - 2rem));
  padding: 0.875rem;
}
.toast[data-tone='error'] {
  border-inline-start-color: var(--aevko-danger, #b42318);
}
.toast[data-tone='warning'] {
  border-inline-start-color: #737373;
}
p {
  color: var(--aevko-muted-foreground, #666);
  margin: 0.25rem 0 0;
}
button {
  background: transparent;
  border: 1px solid var(--aevko-border, #e4e4e7);
  border-radius: 0;
  color: inherit;
  min-block-size: 2rem;
  padding: 0.25rem 0.5rem;
}
button:focus-visible {
  outline: 2px solid var(--aevko-ring, #a3a3a3);
  outline-offset: 2px;
}
.close {
  border: 0;
  font-size: 1.125rem;
  padding: 0 0.25rem;
}
@media (prefers-reduced-motion: no-preference) {
  .toast {
    animation: aevko-toast-in 160ms ease-out;
  }
}
@keyframes aevko-toast-in {
  from {
    opacity: 0;
    transform: translateY(0.5rem);
  }
}
